&lt;li&gt;Fused SiLU+clamp+FP8 quant kernel: &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4416126079&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/24897&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/24897/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/24897&quot;&gt;#24897&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Optimized MHC + DeepGemm pipeline (fused norm, fused hc_head): &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4411398142&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/24775&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/24775/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/24775&quot;&gt;#24775&lt;/a&gt;&lt;/li&gt;
