&lt;li&gt;Multi-detokenizer support: &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4418638156&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/24944&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/24944/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/24944&quot;&gt;#24944&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Pipeline Parallelism + PD support for DeepSeek-V4: &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4406990282&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/24700&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/24700/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/24700&quot;&gt;#24700&lt;/a&gt;&lt;/li&gt;
